import polars as pl

df = pl.DataFrame(
    {"a": [[1, None], [3, 4]]}, schema={"a": pl.Array(pl.Int64, 2)}
)
try:
    print(df.select(pl.col("a").list.drop_nulls()))
except Exception as e:
    print(type(e).__name__)

out = df.select(pl.col("a").arr.to_list().list.drop_nulls())
print(out.schema)
print(out["a"].to_list())
